const row = msg.payload;

const Uw = Number(row.wind_speed_2m_mps);
const Lfl = Number(row.flame_length_m);
const Wfb = Number(row.firebreak_width_m);
const tc = Number(row.burn_time_s);

if ([Uw, Lfl, Wfb, tc].some(v => Number.isNaN(v))) {
    node.error("Missing or invalid numeric input", msg);
    return null;
}

const beta_tx =
    -1.8925 +
    (0.055 * Uw) +
    (0.9418 * Lfl) -
    (0.4469 * Wfb) +
    (0.0114 * tc);

const crossing_probability = Math.exp(beta_tx) / (1 + Math.exp(beta_tx));

let risk_level;
if (crossing_probability < 0.25) {
    risk_level = "moderate";
} else if (crossing_probability < 0.35) {
    risk_level = "transition";
} else if (crossing_probability < 0.45) {
    risk_level = "high";
} else {
    risk_level = "severe";
}

const cross_threshold = Number(row.cross_threshold ?? 0.30);
const predicted_crossed_yes_no =
    crossing_probability >= cross_threshold ? "YES" : "NO";

const result = {
    telemetry_observation_id: row.telemetry_observation_id,
    model_run_id: row.model_run_id,
    firebreak_width_m_snapshot: Wfb,
    beta_tx,
    crossing_probability,
    risk_level,
    predicted_crossed_yes_no
};

msg.payload = result;

msg.params = [
    result.telemetry_observation_id,
    result.model_run_id,
    result.firebreak_width_m_snapshot,
    result.beta_tx,
    result.crossing_probability,
    result.risk_level,
    result.predicted_crossed_yes_no
];

return msg;
